local config = {
  str_homestory_N21yongchi_90020101_1_dialog_content = "Vaya, hace mucho calor...",
  str_homestory_N21yongchi_90020101_2_dialog_content = "Sí, siento que el clima ha sido mucho más cálido últimamente.",
  str_homestory_N21yongchi_90020101_3_dialog_content = "Incluso las plantas en Cloud Gardens parecen haberse hartado del sol.",
  str_homestory_N21yongchi_90020101_4_dialog_content = "Estoy empezando a extrañar Harbor City.",
  str_homestory_N21yongchi_90020101_5_dialog_content = "La brisa, el océano en verano...",
  str_homestory_N21yongchi_90020101_6_dialog_content = "Ah, y poder ir a nadar juntos...",
  str_homestory_N21yongchi_90020101_7_dialog_content = "Sí, no hay ningún lugar para nadar en Cloud Gardens.",
  str_homestory_N21yongchi_90020101_8_dialog_content = "Entonces, ¿tal vez deberíamos hacerlo en alguna parte?",
  str_homestory_N21yongchi_90020101_9_dialog_content = "Creo que a la gente le puede gustar eso.",
  str_homestory_N21yongchi_90020101_10_dialog_content = "¡Buena idea!",
  str_homestory_N21yongchi_90020101_11_dialog_content = "Ya hemos construido muchos edificios. ¿Por qué no tener un parque acuático Cloud Gardens?",
  str_homestory_N21yongchi_90020101_12_dialog_content = "Parece que tienes un plan.",
  str_homestory_N21yongchi_90020101_13_dialog_content = "No todavía. Pero definitivamente quiero un parque acuático.",
  str_homestory_N21yongchi_90020101_14_dialog_content = "Necesitaremos mucha agua. Y en algún lugar para poner el agua.",
  str_homestory_N21yongchi_90020101_15_dialog_content = "Comencemos con la excavación de una piscina.",
  str_homestory_N21yongchi_90020101_16_dialog_content = "Un grupo lo suficientemente grande como para contener muchos Aurorianos significará mucho trabajo preliminar.",
  str_homestory_N21yongchi_90020101_17_dialog_content = "Debe haber un auroriano que sea bueno en la excavación y la construcción. Déjame pensar...",
  str_homestory_N21yongchi_90020101_18_dialog_content = "Eso me recuerda que Ciel es la persona que necesitas. Tiene mucha experiencia en este tipo de trabajo.",
  str_homestory_N21yongchi_90020101_19_dialog_content = "Ciel? ¡Entiendo!",
  str_homestory_N21yongchi_90020101_20_dialog_content = "Iré y hablaré con ella.",
  str_homestory_N21yongchi_90020102_1_dialog_content = "Ciel!",
  str_homestory_N21yongchi_90020102_2_dialog_content = "¡Ay! Oh, eres tú, PlayerName.",
  str_homestory_N21yongchi_90020102_3_dialog_content = "Perdón, ¿te di un susto?",
  str_homestory_N21yongchi_90020102_4_dialog_content = "No. Solo me estaba concentrando en hacer algunos ajustes en Styx.",
  str_homestory_N21yongchi_90020102_5_dialog_content = "¿Hay algo malo con eso?",
  str_homestory_N21yongchi_90020102_6_dialog_content = "Espero que no esté fallando.",
  str_homestory_N21yongchi_90020102_7_dialog_content = "No nada de eso...",
  str_homestory_N21yongchi_90020102_8_dialog_content = "Tuve una idea para algunos ajustes ligeramente radicales.",
  str_homestory_N21yongchi_90020102_9_dialog_content = "PlayerName, sabes que a menudo ayudo al oficial Charon a cavar túneles, ¿no?",
  str_homestory_N21yongchi_90020102_10_dialog_content = "Si estos cambios funcionan, puedo duplicar la velocidad de excavación de Styx.",
  str_homestory_N21yongchi_90020102_11_dialog_content = "¡Wow eso es impresionante!",
  str_homestory_N21yongchi_90020102_12_dialog_content = "El problema es que el rendimiento de la duración se ha reducido en un 90%...",
  str_homestory_N21yongchi_90020102_13_dialog_content = "Eso es... menos increíble.",
  str_homestory_N21yongchi_90020102_14_dialog_content = "Sí, así que tengo que seguir trabajando en ello y ver si puedo encontrar una solución.",
  str_homestory_N21yongchi_90020102_15_dialog_content = "Comprendo.",
  str_homestory_N21yongchi_90020102_16_dialog_content = "Bueno, si hay algo que pueda hacer para ayudar, házmelo saber.",
  str_homestory_N21yongchi_90020102_17_dialog_content = "Oh, ¿en serio?",
  str_homestory_N21yongchi_90020102_18_dialog_content = "En realidad... hay algo que podrías hacer por mí, PlayerName.",
  str_homestory_N21yongchi_90020102_19_dialog_content = "Por supuesto. ¡Nombralo!",
  str_homestory_N21yongchi_90020102_20_dialog_content = "¿Podrías traerme algo de mineral?",
  str_homestory_N21yongchi_90020102_21_dialog_content = "Lo necesito para probar Styx.",
  str_homestory_N21yongchi_90020102_22_dialog_content = "No es un problema. Déjalo conmigo.",
  str_homestory_N21yongchi_90020103_1_dialog_content = "¿Conseguiste el mineral que necesito?",
  str_homestory_N21yongchi_90020103_2_dialog_content = "¡Claro que sí! ({1}/{2})",
  str_homestory_N21yongchi_90020103_3_dialog_content = "¡Gracias! Sabía que podía confiar en ti, PlayerName.",
  str_homestory_N21yongchi_90020103_4_dialog_content = "Y fuiste tan rápido también.",
  str_homestory_N21yongchi_90020103_5_dialog_content = "Jejeje. Creo que todo el trabajo que he estado haciendo aquí en Cloud Gardens me está haciendo más fuerte.",
  str_homestory_N21yongchi_90020103_6_dialog_content = "Trabajos como este parecen súper fáciles ahora.",
  str_homestory_N21yongchi_90020103_7_dialog_content = "Y da la casualidad de que también tengo un favor que pedirte.",
  str_homestory_N21yongchi_90020103_8_dialog_content = "Si lo se. La piscina, ¿verdad?",
  str_homestory_N21yongchi_90020103_9_dialog_content = "¿Eh? ¿Cómo supiste eso, Ciel?",
  str_homestory_N21yongchi_90020103_10_dialog_content = "La señorita Carleen vino a verme mientras recogías el mineral.",
  str_homestory_N21yongchi_90020103_11_dialog_content = "Déjamelo a mí. Todo lo que necesita hacer es delimitar el área donde desea construir la piscina.",
  str_homestory_N21yongchi_90020103_12_dialog_content = "Vendré y ayudaré cuando termine con Styx.",
  str_homestory_N21yongchi_90020103_13_dialog_content = "Bueno. Muchas gracias.",
  str_homestory_N21yongchi_90020103_14_dialog_content = "No lo suficiente.",
  str_homestory_N21yongchi_90020103_15_dialog_content = "Bueno, cuento contigo.",
  str_homestory_N21yongchi_90020104_1_dialog_content = "Huff, puff... Esto debería decirle a Ciel dónde quiero la piscina.",
  str_homestory_N21yongchi_90020104_2_dialog_content = "No estoy acostumbrado a cavar así. Es un trabajo duro.",
  str_homestory_N21yongchi_90020104_3_dialog_content = "Ni siquiera puedo imaginar tener que cavar una piscina entera con una sola mano.",
  str_homestory_N21yongchi_90020104_4_dialog_content = "Pero esto debería ser suficiente. Ahora todo lo que tengo que hacer es esperar a Ciel.",
  str_homestory_N21yongchi_90020104_5_dialog_content = "¡Y hecho!",
  str_homestory_N21yongchi_90020104_6_dialog_content = "¡Guau! Eso es increíble.",
  str_homestory_N21yongchi_90020104_7_dialog_content = "¡Ciel, eres genial!",
  str_homestory_N21yongchi_90020104_8_dialog_content = "Bueno, no fui solo yo. No podría haberlo hecho sin Styx.",
  str_homestory_N21yongchi_90020104_9_dialog_content = "Y la señorita Carleen me dio muchos consejos.",
  str_homestory_N21yongchi_90020104_10_dialog_content = "Pero todavía no se ve perfecto.",
  str_homestory_N21yongchi_90020104_11_dialog_content = "Es posible que necesite hacer un poco de pulido, PlayerName.",
  str_homestory_N21yongchi_90020104_12_dialog_content = "Creo que ya es increíble. Y mucho mejor de lo que yo y mi pala podríamos haber hecho.",
  str_homestory_N21yongchi_90020104_13_dialog_content = "Déjame la limpieza a mí, Ciel.",
  str_homestory_N21yongchi_90020105_1_dialog_content = "¡Sí! He limpiado la piscina y ahora la gente puede usarla.",
  str_homestory_N21yongchi_90020105_2_dialog_content = "Iré y le diré a Carleen.",
  str_homestory_N21yongchi_90020106_1_dialog_content = "¡Carleen!",
  str_homestory_N21yongchi_90020106_2_dialog_content = "PlayerName, estás de vuelta.",
  str_homestory_N21yongchi_90020106_3_dialog_content = "¿Conseguiste el mineral para Ciel?",
  str_homestory_N21yongchi_90020106_4_dialog_content = "Si, lo hice. ¡Y la piscina está construida!",
  str_homestory_N21yongchi_90020106_5_dialog_content = "No sabía que ibas a hablar con Ciel también.",
  str_homestory_N21yongchi_90020106_6_dialog_content = "Sí, de repente pensé en algunas ideas que podrían ayudar.",
  str_homestory_N21yongchi_90020106_7_dialog_content = "Así que fui a verla y se los pasé.",
  str_homestory_N21yongchi_90020106_8_dialog_content = "No pensé que la piscina sería tan rápida de construir.",
  str_homestory_N21yongchi_90020106_9_dialog_content = "Bueno, sigue siendo un poco básico. Es solo la piscina y nada más.",
  str_homestory_N21yongchi_90020106_10_dialog_content = "Yo puedo ayudar con eso.",
  str_homestory_N21yongchi_90020106_11_dialog_content = "Después de todo, has estado trabajando muy duro para darnos la bienvenida a todos.",
  str_homestory_N21yongchi_90020106_12_dialog_content = "No podemos confiar en ti para hacer todo.",
  str_homestory_N21yongchi_90020106_13_dialog_content = "Es de buena educación que nosotros, los invitados, también lo ayudemos.",
  str_homestory_N21yongchi_90020106_14_dialog_content = "Gracias, Carleen.",
  str_homestory_N21yongchi_90020106_15_dialog_content = "Aunque nunca he pensado en ustedes como invitados.",
  str_homestory_N21yongchi_90020106_16_dialog_content = "Estás aquí en Cloud Gardens, y eso te convierte en familia.",
  str_homestory_N21yongchi_90020106_17_dialog_content = "Y el parque acuático Cloud Gardens estará abierto para cualquier auroriano que quiera visitarlo.",
  str_homestory_N21yongchi_90020106_18_dialog_content = "¡Suena genial!",
  str_homestory_N21yongchi_90020201_1_dialog_content = "¡PlayerName!",
  str_homestory_N21yongchi_90020201_2_dialog_content = "Hola, Vice.",
  str_homestory_N21yongchi_90020201_3_dialog_content = "Pasé por una hermosa piscina en el camino aquí. ¿Lo construiste?",
  str_homestory_N21yongchi_90020201_4_dialog_content = "No estaba aquí hace unos días, ¿verdad?",
  str_homestory_N21yongchi_90020201_5_dialog_content = "No. A Carleen se le ocurrió el diseño, luego Ciel hizo el trabajo de construcción.",
  str_homestory_N21yongchi_90020201_6_dialog_content = "¡Creo que es genial también!",
  str_homestory_N21yongchi_90020201_7_dialog_content = "Ah, debería haber adivinado que Carleen contribuyó. Hay un sabor definido de Lumopolis aquí.",
  str_homestory_N21yongchi_90020201_8_dialog_content = "Y es bueno saber que Ciel está encontrando un uso para todas las habilidades de construcción de túneles que ha acumulado.",
  str_homestory_N21yongchi_90020201_9_dialog_content = "¡Exactamente! La piscina no sería tan grande si no fuera por su ayuda.",
  str_homestory_N21yongchi_90020201_10_dialog_content = "Pero no va a ser sólo una piscina. ¡Estoy planeando un parque acuático para que todos puedan nadar y divertirse!",
  str_homestory_N21yongchi_90020201_11_dialog_content = "Eso suena como tú, PlayerName.",
  str_homestory_N21yongchi_90020201_12_dialog_content = "Y ahora me tienes entusiasmado. ¿Cómo puedo ayudar?",
  str_homestory_N21yongchi_90020201_13_dialog_content = "(Tengo un mal presentimiento sobre esto.)",
  str_homestory_N21yongchi_90020201_14_dialog_content = "(Cuando Vice dice ayuda, ¿se refiere a... su cocina?)",
  str_homestory_N21yongchi_90020201_15_dialog_content = "¡Lo se!",
  str_homestory_N21yongchi_90020201_16_dialog_content = "¿Vaya? ¿Q-Qué?",
  str_homestory_N21yongchi_90020201_17_dialog_content = "Recuerdo haber aprendido a nadar en Illumina.",
  str_homestory_N21yongchi_90020201_18_dialog_content = "El entrenador nos dio un equipo de seguridad para ayudar.",
  str_homestory_N21yongchi_90020201_19_dialog_content = "Como balones inflables y salvavidas.",
  str_homestory_N21yongchi_90020201_20_dialog_content = "Así podríamos practicar la natación de forma más segura.",
  str_homestory_N21yongchi_90020201_21_dialog_content = "Y los aurorianos que no habían nadado antes podrían acostumbrarse a estar en el agua.",
  str_homestory_N21yongchi_90020201_22_dialog_content = "Comprendo.",
  str_homestory_N21yongchi_90020201_23_dialog_content = "Supongo que es un poco peligroso simplemente llenar la piscina con agua...",
  str_homestory_N21yongchi_90020201_24_dialog_content = "¡Bien pensado, Vice!",
  str_homestory_N21yongchi_90020201_25_dialog_content = "Jejeje. La seguridad siempre debe ser lo primero.",
  str_homestory_N21yongchi_90020201_26_dialog_content = "Déjame pensar, ¿dónde podríamos conseguir ese tipo de equipo...",
  str_homestory_N21yongchi_90020201_27_dialog_content = "Me parece recordar la última vez que fui a surfear...",
  str_homestory_N21yongchi_90020201_28_dialog_content = "¡Lo sé! El circo tendrá algunos.",
  str_homestory_N21yongchi_90020201_29_dialog_content = "Debería ir y preguntarle a Rainbow.",
  str_homestory_N21yongchi_90020201_30_dialog_content = "¡Sigan con el buen trabajo! Esperaré aquí por ti.",
  str_homestory_N21yongchi_90020202_1_dialog_content = "Es PlayerName! Hola.",
  str_homestory_N21yongchi_90020202_2_dialog_content = "Parece que estás de buen humor. ¿Qué esta pasando?",
  str_homestory_N21yongchi_90020202_3_dialog_content = "Bueno, Cloud Gardens es mi hogar. Estoy feliz de estar de vuelta aquí.",
  str_homestory_N21yongchi_90020202_4_dialog_content = "¿Qué hay de ti, Rainbow? ¿Te estás acomodando?",
  str_homestory_N21yongchi_90020202_5_dialog_content = "Pienso que si. Después de todo, tuve muchas aventuras a bordo del Emerald.",
  str_homestory_N21yongchi_90020202_6_dialog_content = "En todo caso, sospecho que la vida en tierra firme es un poco... excesivamente estable.",
  str_homestory_N21yongchi_90020202_7_dialog_content = "Asi que, PlayerName, ¿por qué el repentino interés en mí?",
  str_homestory_N21yongchi_90020202_8_dialog_content = "Te vi dirigiéndote directamente hacia mí desde MILES de distancia. ¿Necesitas algo?",
  str_homestory_N21yongchi_90020202_9_dialog_content = "Jaja, has visto a través de mí.",
  str_homestory_N21yongchi_90020202_10_dialog_content = "Es así: he construido una piscina en Cloud Gardens y quiero convertirla en un parque acuático.",
  str_homestory_N21yongchi_90020202_11_dialog_content = "Pero aquí hay muchos aurorianos que no saben nadar.",
  str_homestory_N21yongchi_90020202_12_dialog_content = "Así que quería preguntar si hay flotadores de repuesto a bordo del Emerald.",
  str_homestory_N21yongchi_90020202_13_dialog_content = "ah Bueno, has venido a la persona correcta. Estoy a cargo de los almacenes de equipos de seguridad.",
  str_homestory_N21yongchi_90020202_14_dialog_content = "Apuesto a que no esperabas eso.",
  str_homestory_N21yongchi_90020202_15_dialog_content = "¡Ja ja! Bueno, dada la cantidad de trabajos que ya tienes, Rainbow, creo que no debería sorprenderme saber que tienes uno más.",
  str_homestory_N21yongchi_90020202_16_dialog_content = "Entonces, ¿podrías prestarme algunos? O te los puedo comprar?",
  str_homestory_N21yongchi_90020202_17_dialog_content = "Bueno... no creo que pueda. No son míos, pertenecen a la Esmeralda. Solo los cuido.",
  str_homestory_N21yongchi_90020202_18_dialog_content = "Aunque si me pudieras hacer un pequeño favor, PlayerName...",
  str_homestory_N21yongchi_90020202_19_dialog_content = "Cualquier cosa. Solo nómbrelo.",
  str_homestory_N21yongchi_90020202_20_dialog_content = "Heheh, seguro que eres fácil de tratar, PlayerName.",
  str_homestory_N21yongchi_90020202_21_dialog_content = "A nuestro maestro de ceremonias, Jeno, le encanta criar peces. Está fascinado por todas las diferentes especies aquí en Cloud Gardens.",
  str_homestory_N21yongchi_90020202_22_dialog_content = "¿Tal vez podrías atrapar algunos para él? Si haces eso, estoy seguro de que puedo convencerlo de que te dé algunos flotadores.",
  str_homestory_N21yongchi_90020202_23_dialog_content = "Entiendo. Y yo soy un pescador campeón.",
  str_homestory_N21yongchi_90020202_24_dialog_content = "Espera justo ahí. Volveré en dos sacudidas de cola de pez.",
  str_homestory_N21yongchi_90020203_1_dialog_content = "¿Conseguiste el pescado?",
  str_homestory_N21yongchi_90020203_2_dialog_content = "¡Claro que sí!({1}/{2})",
  str_homestory_N21yongchi_90020203_3_dialog_content = "Woah, atrapaste tantos. Déjame echar un vistazo.",
  str_homestory_N21yongchi_90020203_4_dialog_content = "Hmm, este es el más lindo. Parece del tipo que le gustaría a Jeno.",
  str_homestory_N21yongchi_90020203_5_dialog_content = "Dejé los flotadores que querías junto a tu piscina.",
  str_homestory_N21yongchi_90020203_6_dialog_content = "Y también te ha dado un vestuario que usábamos durante las competencias. Es algo básico.",
  str_homestory_N21yongchi_90020203_7_dialog_content = "Pero les dará a los visitantes un lugar para cambiarse y ducharse.",
  str_homestory_N21yongchi_90020203_8_dialog_content = "¡Muchas gracias, Rainbow!",
  str_homestory_N21yongchi_90020203_9_dialog_content = "no lo menciones, PlayerName. Aunque si no estás ocupado, ¿tal vez podrías ir a buscar un poco de agua para mantener a estos peces adentro?",
  str_homestory_N21yongchi_90020203_10_dialog_content = "No creo que tengan suficiente espacio en este momento. Quiero ponerlos en un contenedor más grande antes de llevárselos a Jeno.",
  str_homestory_N21yongchi_90020203_11_dialog_content = "No hay problema. ¡Vuelvo enseguida!",
  str_homestory_N21yongchi_90020203_12_dialog_content = "I'm working on it!",
  str_homestory_N21yongchi_90020203_13_dialog_content = "¡Haz tu mejor esfuerzo!",
  str_homestory_N21yongchi_90020204_1_dialog_content = "¿Entendido?",
  str_homestory_N21yongchi_90020204_2_dialog_content = "¡Hice!",
  str_homestory_N21yongchi_90020204_3_dialog_content = "Eso fue rápido. Bien gracias.",
  str_homestory_N21yongchi_90020204_4_dialog_content = "Y me llevaré estos peces también.",
  str_homestory_N21yongchi_90020204_5_dialog_content = "¡Seguro!",
  str_homestory_N21yongchi_90020204_6_dialog_content = "En camino.",
  str_homestory_N21yongchi_90020204_7_dialog_content = "Un poco de agua lo hará, gracias.",
  str_homestory_N21yongchi_90020205_1_dialog_content = "Bien, eso debería funcionar.",
  str_homestory_N21yongchi_90020205_2_dialog_content = "Y pondré las pelotas inflables cerca.",
  str_homestory_N21yongchi_90020301_1_dialog_content = "PlayerName.",
  str_homestory_N21yongchi_90020301_2_dialog_content = "¡Hola, maestro de ceremonias Jeno!",
  str_homestory_N21yongchi_90020301_3_dialog_content = "¡Simplemente estaba pensando en ti! Quiero preguntarte sobre el nuevo parque acuático: ¿cómo crees que podemos asegurarnos de que sea un éxito?",
  str_homestory_N21yongchi_90020301_4_dialog_content = "¿Parque acuatico?",
  str_homestory_N21yongchi_90020301_5_dialog_content = "Oh sí, Ciel lo mencionó.",
  str_homestory_N21yongchi_90020301_6_dialog_content = "Honestamente, creo que ya se ve genial.",
  str_homestory_N21yongchi_90020301_7_dialog_content = "Pero...",
  str_homestory_N21yongchi_90020301_8_dialog_content = "¿Pero?",
  str_homestory_N21yongchi_90020301_9_dialog_content = "Le falta algo. Algo muy importante.",
  str_homestory_N21yongchi_90020301_10_dialog_content = "Piensa de nuevo. ¿Cuál es tu recuerdo más claro del verano?",
  str_homestory_N21yongchi_90020301_11_option_content = "Picadura de mosquito.",
  str_homestory_N21yongchi_90020301_12_dialog_content = "Eso no. Me refiero a un buen recuerdo.",
  str_homestory_N21yongchi_90020301_13_option_content = "ah ¿Una bebida fría?",
  str_homestory_N21yongchi_90020301_14_dialog_content = "Cerca, pero no.",
  str_homestory_N21yongchi_90020301_15_dialog_content = "Está bien, solo te lo diré.",
  str_homestory_N21yongchi_90020301_16_dialog_content = "Lo que tu parque acuático necesita es... helado.",
  str_homestory_N21yongchi_90020301_17_dialog_content = "La leche y el azúcar se combinan perfectamente a temperaturas bajo cero.",
  str_homestory_N21yongchi_90020301_18_dialog_content = "Golpearte la lengua como fuegos artificiales congelados en el calor abrasador del verano.",
  str_homestory_N21yongchi_90020301_19_dialog_content = "No me gustan los alimentos azucarados. Hacen que la gente aumente de peso. Pero no puedo negar que el helado también hace feliz a la gente.",
  str_homestory_N21yongchi_90020301_20_dialog_content = "¡Entendido!",
  str_homestory_N21yongchi_90020301_21_dialog_content = "Helado, hmm... Hablaré con Vice, ¡hizo raspados el año pasado!",
  str_homestory_N21yongchi_90020301_22_dialog_content = "¡Gracias, Jeno!",
  str_homestory_N21yongchi_90020301_23_dialog_content = "¿Se van tan pronto?",
  str_homestory_N21yongchi_90020301_24_dialog_content = "Qué prisa.",
  str_homestory_N21yongchi_90020302_1_dialog_content = "¡Vice!",
  str_homestory_N21yongchi_90020302_2_dialog_content = "¿Eh? Que pasa, PlayerName? Te quedaste sin aliento.",
  str_homestory_N21yongchi_90020302_3_dialog_content = "¡Sé cómo podemos atraer a más personas al parque acuático Cloud Gardens!",
  str_homestory_N21yongchi_90020302_4_dialog_content = "¿Vaya? Bueno, no me dejes en suspenso.",
  str_homestory_N21yongchi_90020302_5_dialog_content = "¿Recuerdas el año pasado cuando hicimos hielo raspado?",
  str_homestory_N21yongchi_90020302_6_dialog_content = "¿Qué, raspados otra vez?",
  str_homestory_N21yongchi_90020302_7_dialog_content = "Para ser honesto, perdí interés en los helados raspados.",
  str_homestory_N21yongchi_90020302_8_dialog_content = "Porque mis conversaciones con Kleken sobre una franquicia de hielo raspado fracasaron, ¿recuerdas?",
  str_homestory_N21yongchi_90020302_9_dialog_content = "¡No son helados raspados!",
  str_homestory_N21yongchi_90020302_10_dialog_content = "¡Esta vez vamos a hacer helado!",
  str_homestory_N21yongchi_90020302_11_dialog_content = "Entiendo...",
  str_homestory_N21yongchi_90020302_12_dialog_content = "Los granizados son en su mayoría agua, por lo que el sabor siempre es un poco aburrido.",
  str_homestory_N21yongchi_90020302_13_dialog_content = "Pero si le añadimos leche y fruta, o incluso carne... ¡Podemos encontrar millones de tipos diferentes!",
  str_homestory_N21yongchi_90020302_14_dialog_content = "Eh... ¿carne?",
  str_homestory_N21yongchi_90020302_15_dialog_content = "Tienes razón, nunca debí limitarme a raspar hielo. ¡Y puedo agregar una dimensión completamente nueva a tantos alimentos diferentes congelándolos!",
  str_homestory_N21yongchi_90020302_16_dialog_content = "¿Ah?",
  str_homestory_N21yongchi_90020302_17_dialog_content = "¡Gracias! Eres una verdadera inspiración.",
  str_homestory_N21yongchi_90020302_18_dialog_content = "Voy a subir con algunas muestras. PlayerName, encuentra algunas personas para probarlos.",
  str_homestory_N21yongchi_90020302_19_dialog_content = "O tal vez prefieras probar mis inventos tú mismo, PlayerName.",
  str_homestory_N21yongchi_90020302_20_dialog_content = "Estaré a cargo de reclutar probadores. ¡Te pones a trabajar!",
  str_homestory_N21yongchi_90020303_1_dialog_content = "Mmm. ¿A quién debo preguntar?",
  str_homestory_N21yongchi_90020303_2_dialog_content = "¿Por qué, si no es PlayerName!",
  str_homestory_N21yongchi_90020303_3_dialog_content = "¿En qué estás tan sumido en tus pensamientos?",
  str_homestory_N21yongchi_90020303_4_dialog_content = "¡Vaya! brock",
  str_homestory_N21yongchi_90020303_5_dialog_content = "(Recuerdo que Brock puede incluso tomar bebidas de proteína de huevo de gusano de arena).",
  str_homestory_N21yongchi_90020303_6_dialog_content = "(Brock, amigo mío, te pido disculpas por lo que voy a infligirte).",
  str_homestory_N21yongchi_90020303_7_dialog_content = "Oye, ¿cómo es que estás empapado en sudor?",
  str_homestory_N21yongchi_90020303_8_dialog_content = "¿Este? Bueno, acabo de hacer 100 flexiones, 100 abdominales y 100 sentadillas.",
  str_homestory_N21yongchi_90020303_9_dialog_content = "Eso me calentó. Luego corrí durante 10 kilómetros.",
  str_homestory_N21yongchi_90020303_10_dialog_content = "Es la rutina favorita de los miembros de Rediesel Wrench en sus días libres.",
  str_homestory_N21yongchi_90020303_11_dialog_content = "¿Ese es un día libre? De todos modos, debes estar caliente después de tanto ejercicio.",
  str_homestory_N21yongchi_90020303_12_dialog_content = "¿Te gustaría probar un nuevo sabor de helado?",
  str_homestory_N21yongchi_90020303_13_dialog_content = "Te ayudará a reponer tu energía y te hará aún más fuerte.",
  str_homestory_N21yongchi_90020303_14_dialog_content = "¡Suena inteligente!",
  str_homestory_N21yongchi_90020303_15_dialog_content = "¡Sabía que me apoyabas más que a Sinsa!",
  str_homestory_N21yongchi_90020303_16_dialog_content = "Ven entonces. ¿Dónde está este delicioso helado?",
  str_homestory_N21yongchi_90020303_17_dialog_content = "Aquí, ¡pruébalo!",
  str_homestory_N21yongchi_90020303_18_dialog_content = "Lamer lamer.",
  str_homestory_N21yongchi_90020303_19_dialog_content = "Sorber sorber.",
  str_homestory_N21yongchi_90020303_20_dialog_content = "<color=#e8d9bb>¡Kaboom!</color>",
  str_homestory_N21yongchi_90020303_21_dialog_content = "¡Guau!",
  str_homestory_N21yongchi_90020303_22_dialog_content = "¿Cuál es la historia con este helado?",
  str_homestory_N21yongchi_90020303_23_dialog_content = "Cuando lo tragué, sentí como si alguien me hubiera dado un puñetazo en el estómago.",
  str_homestory_N21yongchi_90020303_24_dialog_content = "Eso es un truco furtivo. Incluso más astuto que Sinsa.",
  str_homestory_N21yongchi_90020303_25_dialog_content = "E-espera un minuto. Déjame pensar en un... quiero decir, ¡explícalo!",
  str_homestory_N21yongchi_90020303_26_dialog_content = "¡Lo sé! Tal vez... ¿es una forma de entrenar para recibir un puñetazo?",
  str_homestory_N21yongchi_90020303_27_dialog_content = "Quiero decir, necesitarás más que músculos para vencer a Sinsa, ¿verdad?",
  str_homestory_N21yongchi_90020303_28_dialog_content = "Debes poder seguir luchando, incluso después de recibir un golpe, si quieres reírte el último.",
  str_homestory_N21yongchi_90020303_29_dialog_content = "...",
  str_homestory_N21yongchi_90020303_30_dialog_content = "...",
  str_homestory_N21yongchi_90020303_31_dialog_content = "¡Eres un genio!",
  str_homestory_N21yongchi_90020303_32_dialog_content = "¿Hay más? ¿Puedo tomar un poco de?",
  str_homestory_N21yongchi_90020304_1_dialog_content = "El maestro de ceremonias Jeno.",
  str_homestory_N21yongchi_90020304_2_dialog_content = "Oh hola PlayerName.",
  str_homestory_N21yongchi_90020304_3_dialog_content = "¿Ya has hecho un poco de helado? Debería haber sabido que lo harías.",
  str_homestory_N21yongchi_90020304_4_dialog_content = "Bueno, esto es solo una muestra.",
  str_homestory_N21yongchi_90020304_5_dialog_content = "Pero escuché que eres un verdadero gourmet, así que...",
  str_homestory_N21yongchi_90020304_6_dialog_content = "Lo sé. Quieres que lo pruebe, ¿no?",
  str_homestory_N21yongchi_90020304_7_dialog_content = "No me gustan los alimentos azucarados. Pero fue mi idea, después de todo.",
  str_homestory_N21yongchi_90020304_8_dialog_content = "Déjame probar.",
  str_homestory_N21yongchi_90020304_9_dialog_content = "Sorber sorber.",
  str_homestory_N21yongchi_90020304_10_dialog_content = "¿Q-qué es esto?",
  str_homestory_N21yongchi_90020304_11_dialog_content = "Esto no son fuegos artificiales congelados. Este es un trueno dentro de mi cabeza.",
  str_homestory_N21yongchi_90020304_12_dialog_content = "Es tan... tabú. Un sabor prohibido.",
  str_homestory_N21yongchi_90020304_13_dialog_content = "Sin embargo, tan encantador.",
  str_homestory_N21yongchi_90020304_14_dialog_content = "...",
  str_homestory_N21yongchi_90020304_15_dialog_content = "Jeno, ¿estás bien?",
  str_homestory_N21yongchi_90020304_16_dialog_content = "Toma esto, PlayerName.",
  str_homestory_N21yongchi_90020304_17_dialog_content = "¿Q-qué es?",
  str_homestory_N21yongchi_90020304_18_dialog_content = "Una máquina de helados.",
  str_homestory_N21yongchi_90020304_19_dialog_content = "Mi predecesor me dijo una vez:",
  str_homestory_N21yongchi_90020304_20_dialog_content = "Si alguna vez encuentras a alguien cuyo helado hace vibrar tus papilas gustativas, dale este regalo.",
  str_homestory_N21yongchi_90020304_21_dialog_content = "Esta máquina de helados ha estado con la Esmeralda durante muchos años. Espero que te sirva bien.",
  str_homestory_N21yongchi_90020304_22_dialog_content = "Y que la uses para llevar ese sabor a muchas bocas más.",
  str_homestory_N21yongchi_90020304_23_dialog_content = "Boo-hoo... Estoy conmovido.",
  str_homestory_N21yongchi_90020304_24_dialog_content = "¡Gracias, Jeno!",
  str_homestory_N21yongchi_90020305_1_dialog_content = "¡Vicio, he vuelto!",
  str_homestory_N21yongchi_90020305_2_dialog_content = "Excelente, PlayerName.",
  str_homestory_N21yongchi_90020305_3_dialog_content = "¿Qué pensaron todos de mi helado?",
  str_homestory_N21yongchi_90020305_4_dialog_content = "¡Bien! Brock lo calificó muy alto.",
  str_homestory_N21yongchi_90020305_5_dialog_content = "Dijo que sería de gran ayuda en su rutina de entrenamiento físico.",
  str_homestory_N21yongchi_90020305_6_dialog_content = "Mmm. No sabía que era un hombre de tan buen gusto.",
  str_homestory_N21yongchi_90020305_7_dialog_content = "De hecho, agregué una lata de una nueva carne enlatada nutritiva de Illumina a la mezcla.",
  str_homestory_N21yongchi_90020305_8_dialog_content = "Entonces, ¿por qué hay que añadir carne al helado...",
  str_homestory_N21yongchi_90020305_9_dialog_content = "Vaya. ¿Alguna otra reseña?",
  str_homestory_N21yongchi_90020305_10_dialog_content = "¡Sí! Jeno dijo que estaba delicioso.",
  str_homestory_N21yongchi_90020305_11_dialog_content = "Y hasta nos regaló esta máquina de helados.",
  str_homestory_N21yongchi_90020305_12_dialog_content = "¡Impresionante! Eso significa que seguro que todos disfrutarán de mi nuevo helado.",
  str_homestory_N21yongchi_90020305_13_dialog_content = "Y con esta máquina para ayudar, será aún más fácil hacerlos.",
  str_homestory_N21yongchi_90020305_14_dialog_content = "Seremos tan eficientes como una fábrica de conservas de carne.",
  str_homestory_N21yongchi_90020305_15_dialog_content = "Comparación extraña, pero bueno...",
  str_homestory_N21yongchi_90020305_16_dialog_content = "¿Debería probarlos yo también, antes de ofrecerlos al público...",
  str_homestory_N21yongchi_90020306_1_dialog_content = "Está bien, todo está aclarado.",
  str_homestory_N21yongchi_90020306_2_dialog_content = "Ahora todos pueden disfrutar del helado de Vice.",
  str_homestory_N21yongchi_90020306_3_dialog_content = "Mmm. ¿Debo probar uno, o no?",
  str_homestory_N21yongchi_90020306_4_dialog_content = "Ja ja. Olvídalo, tal vez tenga uno más tarde.",
  str_homestory_N21yongchi_90020401_1_dialog_content = "PlayerName.",
  str_homestory_N21yongchi_90020401_2_dialog_content = "¡Oficial Viviana!",
  str_homestory_N21yongchi_90020401_3_dialog_content = "Pareces preocupado por algo. ¿Puedo ser de alguna ayuda?",
  str_homestory_N21yongchi_90020401_4_dialog_content = "Vaya, ¿cómo podrías saberlo?",
  str_homestory_N21yongchi_90020401_5_dialog_content = "Impresionante Caelestite de hecho, capaz de sentir la más mínima emoción de los demás.",
  str_homestory_N21yongchi_90020401_6_dialog_content = "Ja ja. Tal vez la forma en que tus cejas están fruncidas ayudó.",
  str_homestory_N21yongchi_90020401_7_dialog_content = "Déjame adivinar. ¿Otra vez ha desaparecido el oficial Philyshy?",
  str_homestory_N21yongchi_90020401_8_dialog_content = "Sí, y está atrasada con un importante informe de inteligencia.",
  str_homestory_N21yongchi_90020401_9_dialog_content = "Nadie puede encontrarla en ninguna parte.",
  str_homestory_N21yongchi_90020401_10_dialog_content = "Ella es un verdadero dolor de cabeza.",
  str_homestory_N21yongchi_90020401_11_dialog_content = "(Philyshy ha estado escabulléndose para tomar siestas últimamente... ¿quizás está cerca del agua?)",
  str_homestory_N21yongchi_90020401_12_dialog_content = "Creo que tengo una idea de dónde podría estar.",
  str_homestory_N21yongchi_90020401_13_dialog_content = "¿En serio? Sería de gran ayuda si pudieras encontrarla.",
  str_homestory_N21yongchi_90020401_14_dialog_content = "Espera mientras voy a buscarla.",
  str_homestory_N21yongchi_90020401_15_dialog_content = "Oh gracias, PlayerName!",
  str_homestory_N21yongchi_90020402_1_dialog_content = "¡Oye! ¡Paloma!",
  str_homestory_N21yongchi_90020402_2_dialog_content = "Waaaaaaaaaaaaah—",
  str_homestory_N21yongchi_90020402_3_dialog_content = "¿Quién es? ¿Quién está haciendo tal alboroto?",
  str_homestory_N21yongchi_90020402_4_dialog_content = "PlayerName, ¿eres tu?",
  str_homestory_N21yongchi_90020402_5_dialog_content = "¿Por qué estás holgazaneando aquí, Dove?",
  str_homestory_N21yongchi_90020402_6_dialog_content = "¿S-holgazaneando? ¡No soy!",
  str_homestory_N21yongchi_90020402_7_dialog_content = "Solo quería tomar una siesta porque he estado trabajando muy duro. Y luego me diste tanto susto.",
  str_homestory_N21yongchi_90020402_8_dialog_content = "¿Vaya? Entonces, ¿has terminado de entregar todos tus correos?",
  str_homestory_N21yongchi_90020402_9_dialog_content = "Oh, los correos... Me pondré en eso, tan pronto como me haya puesto al día con mi sueño.",
  str_homestory_N21yongchi_90020402_10_dialog_content = "¿Y qué estás haciendo de todos modos? No puedes perturbar mi sueño así sin darte explicaciones.",
  str_homestory_N21yongchi_90020402_11_dialog_content = "Oh sí. Lo lamento. En realidad estaba buscando a Philyshy.",
  str_homestory_N21yongchi_90020402_12_dialog_content = "Toma, ten un cupón para un helado como disculpa. Si estás cerca de la piscina, puedes probar uno de los nuevos sabores de Vice.",
  str_homestory_N21yongchi_90020402_13_dialog_content = "Bueno. Supongo que te perdonaré entonces. Pero no sé dónde está Philyshy.",
  str_homestory_N21yongchi_90020402_14_dialog_content = "De todos modos, sería más probable que visitara si la piscina tuviera un lugar para dormir. Eso es más importante que el helado, creo.",
  str_homestory_N21yongchi_90020402_15_dialog_content = "¿Quizás un sillón bajo una sombrilla?",
  str_homestory_N21yongchi_90020402_16_dialog_content = "Solo lo esencial para que los trabajadores podamos relajarnos adecuadamente.",
  str_homestory_N21yongchi_90020402_17_dialog_content = "Estás bien. Déjame pensar.",
  str_homestory_N21yongchi_90020402_18_dialog_content = "Un lugar para relajarse... para relajarse... Philyshy... ¡Entendido!",
  str_homestory_N21yongchi_90020402_19_dialog_content = "¡No olvides visitar el parque acuático, Paloma!",
  str_homestory_N21yongchi_90020402_20_dialog_content = "¿Eh? Bien, seguro.",
  str_homestory_N21yongchi_90020403_1_dialog_content = "PlayerName, ¿Que estas haciendo?",
  str_homestory_N21yongchi_90020403_2_dialog_content = "Estoy a punto de hacer unos sillones de madera.",
  str_homestory_N21yongchi_90020403_3_dialog_content = "¿Qué piensas? Son buenos, ¿verdad?",
  str_homestory_N21yongchi_90020403_4_dialog_content = "Sí. Conocía tus habilidades de mando en el campo de batalla, pero... Parece que todavía tienes algunas sorpresas escondidas.",
  str_homestory_N21yongchi_90020403_5_dialog_content = "Ahora cualquiera que venga a visitar el parque acuático puede descansar cuando quiera.",
  str_homestory_N21yongchi_90020403_6_dialog_content = "Este parque acuático cada vez es más cómodo.",
  str_homestory_N21yongchi_90020403_7_dialog_content = "Sí. Ahora las personas pueden tener un lugar para acostarse si se cansan de nadar o si quieren disfrutar de un helado.",
  str_homestory_N21yongchi_90020403_8_dialog_content = "Y eso no es lo mejor. Estos sillones tienen un poder secreto.",
  str_homestory_N21yongchi_90020403_9_dialog_content = "¿Un poder secreto?",
  str_homestory_N21yongchi_90020403_10_dialog_content = "Una vez que los haya hecho y configurado, ¡podrás ver los resultados!",
  str_homestory_N21yongchi_90020404_1_dialog_content = "Bien, todo esto está limpio y reluciente ahora.",
  str_homestory_N21yongchi_90020404_2_dialog_content = "Ahora todo lo que tengo que hacer es sacar las tumbonas y esperar a que suceda la magia.",
  str_homestory_N21yongchi_90020404_3_dialog_content = "Y debería aprovechar la oportunidad para traer a la oficial Vivian.",
  str_homestory_N21yongchi_90020405_1_dialog_content = "Zzzz... Zzzz... miau.",
  str_homestory_N21yongchi_90020405_2_dialog_content = "¡Funcionó! ¡Seguir las huellas condujo a Philyshy!",
  str_homestory_N21yongchi_90020405_3_dialog_content = "¿Cómo es que pareces dormido incluso cuando estás de pie?",
  str_homestory_N21yongchi_90020405_4_dialog_content = "¿Eh? Tranquilizarse, PlayerName. Acabo de despertarme.",
  str_homestory_N21yongchi_90020405_5_dialog_content = "Bueno, será mejor que dejes de dormir.",
  str_homestory_N21yongchi_90020405_6_dialog_content = "Alguien te está buscando.",
  str_homestory_N21yongchi_90020405_7_dialog_content = "¿Q-Quién miau? Sólo he estado despierto durante cinco minutos. Necesito...",
  str_homestory_N21yongchi_90020405_8_dialog_content = "Phi-ly-tímido-!",
  str_homestory_N21yongchi_90020405_9_dialog_content = "¡¿Maullar?!",
  str_homestory_N21yongchi_90020405_10_dialog_content = "O-Oficial Vivian?",
  str_homestory_N21yongchi_90020405_11_dialog_content = "¿P-Por qué estás aquí miau?",
  str_homestory_N21yongchi_90020405_12_dialog_content = "¿Por qué no has entregado la información que te pedí?",
  str_homestory_N21yongchi_90020405_13_dialog_content = "¿Y por qué no puedo encontrarte en ningún lado? No me estarías evitando, ¿verdad?",
  str_homestory_N21yongchi_90020405_14_dialog_content = "A-¿Evitandote? Como si yo...",
  str_homestory_N21yongchi_90020405_15_dialog_content = "D-Déjame explicarte miau...",
  str_homestory_N21yongchi_90020405_16_dialog_content = "Está bien, puedes hacer eso en nuestro camino de regreso.",
  str_homestory_N21yongchi_90020405_17_dialog_content = "Y no se preocupe si no puede explicarlo completamente ahora. Tengo mucho tiempo esta noche para escuchar una explicación completa y completa.",
  str_homestory_N21yongchi_90020405_18_dialog_content = "Oh miau Tienes un aspecto aterrador, oficial Vivian.",
  str_homestory_N21yongchi_90020405_19_dialog_content = "Todo esto es debido a PlayerName y ese hermoso sillón.",
  str_homestory_N21yongchi_90020405_20_dialog_content = "Iré contigo como lo ordenaste miau.",
  str_homestory_N21yongchi_90020405_21_dialog_content = "PlayerName¿Es ese el poder secreto que mencionaste?",
  str_homestory_N21yongchi_90020405_22_dialog_content = "Una trampa Philyshy... muy inteligente.",
  str_homestory_N21yongchi_90020405_23_dialog_content = "Claro que sí. Supuse que probablemente se estaba escondiendo deliberadamente de todos, pero no sería capaz de resistirse a un cómodo lugar de descanso.",
  str_homestory_N21yongchi_90020405_24_dialog_content = "Y efectivamente, ella apareció.",
  str_homestory_N21yongchi_90020405_25_dialog_content = "Ahora estoy seguro de que las tumbonas son cómodas.",
  str_homestory_N21yongchi_90020501_1_dialog_content = "¡PlayerName!",
  str_homestory_N21yongchi_90020501_2_dialog_content = "¿Qué te preocupa tanto?",
  str_homestory_N21yongchi_90020501_3_dialog_content = "El parque acuático se ve hermoso. ¿Te molesta algo más?",
  str_homestory_N21yongchi_90020501_4_dialog_content = "Bueno... quiero hacerlo aún mejor, para que más personas puedan disfrutarlo.",
  str_homestory_N21yongchi_90020501_5_dialog_content = "He intentado agregar algunas plantas al agua para que el aire sea más fresco.",
  str_homestory_N21yongchi_90020501_6_dialog_content = "Y también abrir algunos puestos de comida más.",
  str_homestory_N21yongchi_90020501_7_dialog_content = "Incluso he pensado en tener bolsas ciegas para vender como lo hace Jomu.",
  str_homestory_N21yongchi_90020501_8_dialog_content = "Oh, bolsas ciegas... Yo no haría eso.",
  str_homestory_N21yongchi_90020501_9_dialog_content = "¿Y hay algo más que le gustaría mejorar?",
  str_homestory_N21yongchi_90020501_10_dialog_content = "No estoy seguro. Sigo pensando que falta algo cuando lo comparo con mis recuerdos de la Esmeralda.",
  str_homestory_N21yongchi_90020501_11_dialog_content = "Tal vez no es tan... animado?",
  str_homestory_N21yongchi_90020501_12_dialog_content = "Parece sentirse un poco triste.",
  str_homestory_N21yongchi_90020501_13_dialog_content = "Tal vez necesites a alguien como Rainbow, un anfitrión para entusiasmar a todos.",
  str_homestory_N21yongchi_90020501_14_dialog_content = "La gente se animará si tenemos a alguien que pueda crear un ambiente alegre.",
  str_homestory_N21yongchi_90020501_15_dialog_content = "Eso tiene sentido.",
  str_homestory_N21yongchi_90020501_16_dialog_content = "Pero no puedo andar por la piscina haciendo eso todo el tiempo.",
  str_homestory_N21yongchi_90020501_17_dialog_content = "Déjame pensar. ¿Cómo crear una atmósfera?",
  str_homestory_N21yongchi_90020501_18_dialog_content = "¿Qué tal un poco de música? Muchos lugares diferentes utilizan la música para crear la atmósfera adecuada.",
  str_homestory_N21yongchi_90020501_19_dialog_content = "En Umbraton, algunas tiendas ponen música clásica para que los clientes se sientan relajados y como en casa.",
  str_homestory_N21yongchi_90020501_20_dialog_content = "Y eso significa que gastan más.",
  str_homestory_N21yongchi_90020501_21_dialog_content = "Pero, ¿dónde voy a encontrar el equipo?",
  str_homestory_N21yongchi_90020501_22_dialog_content = "Creo recordar la música en el Emerald.",
  str_homestory_N21yongchi_90020501_23_dialog_content = "Si, tienes razón. Lo jugaron entre las competiciones.",
  str_homestory_N21yongchi_90020501_24_dialog_content = "Entonces debería ir y preguntarle a Rainbow otra vez.",
  str_homestory_N21yongchi_90020502_1_dialog_content = "¡Rainbow!",
  str_homestory_N21yongchi_90020502_2_dialog_content = "PlayerName, estás todo sudoroso otra vez. ¿Cual es la prisa?",
  str_homestory_N21yongchi_90020502_3_dialog_content = "Te dije que no te apuraras tanto. No voy a ir a ninguna parte de todos modos.",
  str_homestory_N21yongchi_90020502_4_dialog_content = "¿A todos les gustaron esos regalos que te di?",
  str_homestory_N21yongchi_90020502_5_dialog_content = "¡Sí! Gracias, Rainbow. Y Jeno también.",
  str_homestory_N21yongchi_90020502_6_dialog_content = "Muchos Aurorianos que no saben nadar pueden disfrutar del parque acuático, gracias a ustedes dos.",
  str_homestory_N21yongchi_90020502_7_dialog_content = "Jejeje. Parece que los aurorianos tienen una afinidad natural por el agua.",
  str_homestory_N21yongchi_90020502_8_dialog_content = "¿Quién puede resistirse a un buen flotador relajante?",
  str_homestory_N21yongchi_90020502_9_dialog_content = "Bueno, mientras te gusten. Entonces, ¿qué es esta vez?",
  str_homestory_N21yongchi_90020502_10_dialog_content = "Bueno... me gustaría poder tocar música en el parque acuático.",
  str_homestory_N21yongchi_90020502_11_dialog_content = "Vaya. Eso no será barato.",
  str_homestory_N21yongchi_90020502_12_dialog_content = "Y no es algo que pueda decidir por mí mismo. Deberías hablar con Jeno.",
  str_homestory_N21yongchi_90020502_13_dialog_content = "Él no es sólo un pintor entusiasta, ya sabes. También tiene muchas ideas sobre la música.",
  str_homestory_N21yongchi_90020502_14_dialog_content = "Es un hombre muy culto, para un marinero.",
  str_homestory_N21yongchi_90020502_15_dialog_content = "Ja ja. Gracias, arcoiris.",
  str_homestory_N21yongchi_90020502_16_dialog_content = "Iré y hablaré con él.",
  str_homestory_N21yongchi_90020503_1_dialog_content = "PlayerName.",
  str_homestory_N21yongchi_90020503_2_dialog_content = "¿Cómo es que tengo una sensación extraña en el estómago cuando te veo?",
  str_homestory_N21yongchi_90020503_3_dialog_content = "Tal vez... ¿tiene algo que ver con ese helado?",
  str_homestory_N21yongchi_90020503_4_dialog_content = "Creo que sí. No recuerdo el sabor, pero el recuerdo de esa experiencia sigue siendo muy claro.",
  str_homestory_N21yongchi_90020503_5_dialog_content = "Aunque parece ser mi estómago el que lo recuerda, no yo.",
  str_homestory_N21yongchi_90020503_6_dialog_content = "es extraño Muy extraño de hecho.",
  str_homestory_N21yongchi_90020503_7_dialog_content = "Bueno, si quieres más, siempre eres bienvenido en el parque acuático Cloud Gardens.",
  str_homestory_N21yongchi_90020503_8_dialog_content = "Gracias. Pero trato de evitar los alimentos azucarados.",
  str_homestory_N21yongchi_90020503_9_dialog_content = "Si engordara, no tendría la flexibilidad que necesito para mis espectáculos de magia.",
  str_homestory_N21yongchi_90020503_10_dialog_content = "Oh, ¿pero era dulce? ¿Por qué mi cerebro se vuelve confuso cada vez que trato de recordar ese sabor?",
  str_homestory_N21yongchi_90020503_11_dialog_content = "Está bien, claro, er, hablemos del helado en otro momento.",
  str_homestory_N21yongchi_90020503_12_dialog_content = "Necesito un favor, Jeno. ¿Dónde puedo comprar algunos equipos de música?",
  str_homestory_N21yongchi_90020503_13_dialog_content = "Ah, claro. Quieres poner música en el parque acuático y crear un mejor ambiente, ¿verdad?",
  str_homestory_N21yongchi_90020503_14_dialog_content = "Debería haber sabido que adivinarías bien, Jeno.",
  str_homestory_N21yongchi_90020503_15_dialog_content = "Por supuesto. Y es una curiosa coincidencia...",
  str_homestory_N21yongchi_90020503_16_dialog_content = "Resulta que tengo algunos equipos viejos que podría venderte.",
  str_homestory_N21yongchi_90020503_17_dialog_content = "Oh gracias-",
  str_homestory_N21yongchi_90020503_18_dialog_content = "Por 50 millones de Nightiums.",
  str_homestory_N21yongchi_90020503_19_dialog_content = "¿¡Qué!?",
  str_homestory_N21yongchi_90020503_20_dialog_content = "E-eso es demasiado.",
  str_homestory_N21yongchi_90020503_21_dialog_content = "De nada. Estamos hablando de una plataforma de DJ coleccionable muy rara. Pagué el doble por él cuando lo adquirí.",
  str_homestory_N21yongchi_90020503_22_dialog_content = "Pero como somos amigos, no se sentiría bien venderte el legendario DJ Deck Suffering Knight.",
  str_homestory_N21yongchi_90020503_23_dialog_content = "Y no es algo a lo que me gustaría ponerle un valor monetario.",
  str_homestory_N21yongchi_90020503_24_dialog_content = "Pero necesito que demuestres que eres digno de ello.",
  str_homestory_N21yongchi_90020503_25_dialog_content = "He pasado innumerables días felices con él. Tienes que demostrarme que lo cuidarás.",
  str_homestory_N21yongchi_90020503_26_dialog_content = "(Oh, lo entiendo. Jeno es en realidad una persona muy nostálgica).",
  str_homestory_N21yongchi_90020503_27_dialog_content = "Entonces, ¡muéstrame cuánto lo quieres!",
  str_homestory_N21yongchi_90020503_28_dialog_content = "Al traerme los peces más raros y valiosos que se encuentran en estas partes.",
  str_homestory_N21yongchi_90020503_29_dialog_content = "¡Lo haré!",
  str_homestory_N21yongchi_90020504_1_dialog_content = "¿Los recibiste?",
  str_homestory_N21yongchi_90020504_2_dialog_content = "¡Hice!({1}/{2})",
  str_homestory_N21yongchi_90020504_3_dialog_content = "No pensé que serías capaz de hacerlo.",
  str_homestory_N21yongchi_90020504_4_dialog_content = "Pero guárdalos. Realmente nunca los quise.",
  str_homestory_N21yongchi_90020504_5_dialog_content = "Sólo quería ver qué tan determinado estabas. Qué duro trabajarías.",
  str_homestory_N21yongchi_90020504_6_dialog_content = "Entonces, ¿pasé la prueba?",
  str_homestory_N21yongchi_90020504_7_dialog_content = "Por supuesto. El deck de DJ es tuyo.",
  str_homestory_N21yongchi_90020504_8_dialog_content = "Y estoy seguro de que sus hermosos tonos te brindarán una mayor comprensión de la verdad de este mundo.",
  str_homestory_N21yongchi_90020504_9_dialog_content = "Por favor, cuídalo bien.",
  str_homestory_N21yongchi_90020504_10_dialog_content = "¡Por supuesto, Jeno! Voy a.",
  str_homestory_N21yongchi_90020504_11_dialog_content = "Almost there!",
  str_homestory_N21yongchi_90020504_12_dialog_content = "Bien. Pruébamelo.",
  str_homestory_N21yongchi_90020505_1_dialog_content = "¡Sí! Ahora que hemos despejado un espacio, podemos configurar el DJ Deck Suffering Knight.",
  str_homestory_N21yongchi_90020505_2_dialog_content = "Aunque... ¿cómo funciona realmente?",
  str_homestory_N21yongchi_90020601_1_dialog_content = "PlayerName.",
  str_homestory_N21yongchi_90020601_2_dialog_content = "...",
  str_homestory_N21yongchi_90020601_3_dialog_content = "¡PlayerName!",
  str_homestory_N21yongchi_90020601_4_dialog_content = "...",
  str_homestory_N21yongchi_90020601_5_dialog_content = "¡Maldita Caelestita!",
  str_homestory_N21yongchi_90020601_6_dialog_content = "¿Eh? ¿Qué?",
  str_homestory_N21yongchi_90020601_7_dialog_content = "¡Fia, eres tú!",
  str_homestory_N21yongchi_90020601_8_dialog_content = "Estabas a kilómetros de distancia. ¿Qué tienes en mente?",
  str_homestory_N21yongchi_90020601_9_dialog_content = "Seguiste ignorándome. Un extrozoólogo como yo merece más respeto.",
  str_homestory_N21yongchi_90020601_10_dialog_content = "¡Lo siento lo siento!",
  str_homestory_N21yongchi_90020601_11_dialog_content = "Estaba soñando despierto, imaginando a mucha gente disfrutando del parque acuático.",
  str_homestory_N21yongchi_90020601_12_dialog_content = "Tch. Te perdonaré, supongo.",
  str_homestory_N21yongchi_90020601_13_dialog_content = "Y, er... En realidad, me encantaría entrar y disfrutar de la piscina.",
  str_homestory_N21yongchi_90020601_14_dialog_content = "¿Vaya? Entra. Es gratis.",
  str_homestory_N21yongchi_90020601_15_dialog_content = "¡No me preocupaba el precio!",
  str_homestory_N21yongchi_90020601_16_dialog_content = "¿H-Lo has olvidado?",
  str_homestory_N21yongchi_90020601_17_dialog_content = "No soy... Bueno, no soy el mejor nadador.",
  str_homestory_N21yongchi_90020601_18_dialog_content = "Oh sí. Ahora recuerdo.",
  str_homestory_N21yongchi_90020601_19_dialog_content = "¿Por qué no probar con un flotador?",
  str_homestory_N21yongchi_90020601_20_dialog_content = "Eh. Esos son para niños. ¡No quiero uno de esos!",
  str_homestory_N21yongchi_90020601_21_dialog_content = "Entonces solo hay una opción.",
  str_homestory_N21yongchi_90020601_22_dialog_content = "Si no quieres usar un flotador, tendrás que aprender a nadar.",
  str_homestory_N21yongchi_90020601_23_dialog_content = "Exactamente. Por eso vine a hablarte, PlayerName.",
  str_homestory_N21yongchi_90020601_24_dialog_content = "Te ofrezco una buena oportunidad para que me ayudes, la gran belleza extrozoóloga, ya sabes.",
  str_homestory_N21yongchi_90020601_25_dialog_content = "¡No te lo pierdas!",
  str_homestory_N21yongchi_90020601_26_dialog_content = "Pero... necesito dar la bienvenida a todos, mantener los vestuarios ordenados y limpiar los pisos y la piscina.",
  str_homestory_N21yongchi_90020601_27_dialog_content = "Me temo que no tengo tiempo para enseñarte, Fia.",
  str_homestory_N21yongchi_90020601_28_dialog_content = "Oh... ¿Me estás rechazando?",
  str_homestory_N21yongchi_90020601_29_dialog_content = "No, no, ¿cómo podría hacer eso?",
  str_homestory_N21yongchi_90020601_30_dialog_content = "¿Qué tal esto? Haré que Vice te enseñe.",
  str_homestory_N21yongchi_90020601_31_dialog_content = "Ella es mucho mejor nadadora que yo.",
  str_homestory_N21yongchi_90020601_32_dialog_content = "Mmm. ¿Vicio?",
  str_homestory_N21yongchi_90020601_33_dialog_content = "Bien entonces. Veo que tienes mucho trabajo, PlayerName.",
  str_homestory_N21yongchi_90020601_34_dialog_content = "Así que no sería educado de mi parte insistir.",
  str_homestory_N21yongchi_90020601_35_dialog_content = "Aquí hay algunos pequeños obsequios como agradecimiento.",
  str_homestory_N21yongchi_90020601_36_dialog_content = "¡Gracias, Fía!",
  str_homestory_N21yongchi_90020601_37_dialog_content = "¡Sí! Una vez que haya aprendido, podemos ir a nadar juntos.",
  str_homestory_N21yongchi_90020601_38_dialog_content = "Bueno. Iré a buscar a Vice.",
  str_homestory_N21yongchi_90020601_39_dialog_content = "Por supuesto. Esperaré aquí por ti.",
  str_homestory_N21yongchi_90020602_1_dialog_content = "Mmm. Esa colchoneta inflable...",
  str_homestory_N21yongchi_90020602_2_dialog_content = "Es muy del estilo de Fia.",
  str_homestory_N21yongchi_90020602_3_dialog_content = "Creo que debería mover un poco la silla inflable.",
  str_homestory_N21yongchi_90020602_4_dialog_content = "Los guardaré por ahora en caso de que alguno de los visitantes se tropiece con ellos.",
  str_homestory_N21yongchi_90020603_1_dialog_content = "¿Vicio? ¿Qué haces en la Torre Blanca? Te estoy buscando.",
  str_homestory_N21yongchi_90020603_2_dialog_content = "¡Mmm! ¡PlayerName! Te estoy buscando a ti también.",
  str_homestory_N21yongchi_90020603_3_dialog_content = "¿Qué paso?",
  str_homestory_N21yongchi_90020603_4_dialog_content = "<color=#e8d9bb>¡Toc, toc!</color>",
  str_homestory_N21yongchi_90020603_5_dialog_content = "Es un poco vergonzoso... Parece que la máquina de helados está rota.",
  str_homestory_N21yongchi_90020603_6_dialog_content = "¿Roto?",
  str_homestory_N21yongchi_90020603_7_dialog_content = "No estoy realmente seguro.",
  str_homestory_N21yongchi_90020603_8_dialog_content = "Simplemente se detuvo. Y disfruté mucho haciendo todos mis nuevos sabores de helado.",
  str_homestory_N21yongchi_90020603_9_dialog_content = "¡Ah! ¡Vamos! ¿Cómo lo guardamos? ¿No prometimos que les daríamos a todos un gran verano?",
  str_homestory_N21yongchi_90020603_10_dialog_content = "Parece que tú y la máquina de helados os habéis vuelto buenos amigos.",
  str_homestory_N21yongchi_90020603_11_dialog_content = "¡Por supuesto! Hemos estado trabajando duro codo con codo durante 20 horas, sin parar.",
  str_homestory_N21yongchi_90020603_12_dialog_content = "¡20 horas! Vice, necesitas tomarte un descanso.",
  str_homestory_N21yongchi_90020603_13_dialog_content = "Y sospecho que el problema con la máquina podría estar relacionado con el exceso de trabajo.",
  str_homestory_N21yongchi_90020603_14_dialog_content = "Mmm. Puede que haya pasado por alto esa posibilidad.",
  str_homestory_N21yongchi_90020603_15_dialog_content = "Tal vez es mi culpa que se rompiera... Y después de que te tomaste tantas molestias para conseguirlo. Lo siento, PlayerName.",
  str_homestory_N21yongchi_90020603_16_dialog_content = "Estaba planeando un sabor absolutamente alucinante para que te des un festín.",
  str_homestory_N21yongchi_90020603_17_dialog_content = "Bueno, es el pensamiento lo que cuenta.",
  str_homestory_N21yongchi_90020603_18_dialog_content = "¿Estaba actuando raro antes de que dejara de funcionar?",
  str_homestory_N21yongchi_90020603_19_dialog_content = "Déjame pensar. Creo que podría haber habido una luz roja intermitente.",
  str_homestory_N21yongchi_90020603_20_dialog_content = "Entonces, ¿tal vez no estaba recibiendo suficiente energía?",
  str_homestory_N21yongchi_90020603_21_dialog_content = "Si recuerdas las imágenes de arriba. Hay un árbol y una roca.",
  str_homestory_N21yongchi_90020603_22_dialog_content = "¿Quizás podríamos alimentarlo con algo de madera y mineral y ver qué pasa?",
  str_homestory_N21yongchi_90020603_23_dialog_content = "Aunque no veo por qué una máquina de helados funcionaría con madera y mineral.",
  str_homestory_N21yongchi_90020603_24_dialog_content = "Iré a buscar un poco de todos modos. Veremos que pasa.",
  str_homestory_N21yongchi_90020604_1_dialog_content = "¿Conseguiste la madera?",
  str_homestory_N21yongchi_90020604_2_dialog_content = "Claro que sí.({1}/{2})",
  str_homestory_N21yongchi_90020604_3_dialog_content = "¡Gracias! Ahora ve y encuentra algo de mineral.",
  str_homestory_N21yongchi_90020604_4_dialog_content = "Servirá.",
  str_homestory_N21yongchi_90020604_5_dialog_content = "No lo suficiente.",
  str_homestory_N21yongchi_90020604_6_dialog_content = "¡Buena suerte! Estaré aquí.",
  str_homestory_N21yongchi_90020605_1_dialog_content = "¿Tienes el mineral también?",
  str_homestory_N21yongchi_90020605_2_dialog_content = "Sip.({1}/{2})",
  str_homestory_N21yongchi_90020605_3_dialog_content = "Siempre eres tan rápido, PlayerName.",
  str_homestory_N21yongchi_90020605_4_dialog_content = "Veamos si funciona.",
  str_homestory_N21yongchi_90020605_5_dialog_content = "Bien, he puesto todo.",
  str_homestory_N21yongchi_90020605_6_dialog_content = "Nada cambiará si no le damos una oportunidad. Toma, lo haré.",
  str_homestory_N21yongchi_90020605_7_dialog_content = "<color=#e8d9bb>crujido crujido.</color>",
  str_homestory_N21yongchi_90020605_8_dialog_content = "<color=#e8d9bb>crujido crujido.</color>",
  str_homestory_N21yongchi_90020605_9_dialog_content = "Espero que esto funcione.",
  str_homestory_N21yongchi_90020605_10_dialog_content = "Todo lo que podemos hacer ahora es orar.",
  str_homestory_N21yongchi_90020605_11_dialog_content = "crujido crujido.",
  str_homestory_N21yongchi_90020605_12_dialog_content = "Eh... Vicio...",
  str_homestory_N21yongchi_90020605_13_dialog_content = "Sólo quiero preguntar... No maltrataste la máquina de helados, ¿verdad?",
  str_homestory_N21yongchi_90020605_14_dialog_content = "Ja ja. Como si fuera a hacer eso.",
  str_homestory_N21yongchi_90020605_15_dialog_content = "crujido crujido.",
  str_homestory_N21yongchi_90020605_16_dialog_content = "Crujido crujido crujido crujido.",
  str_homestory_N21yongchi_90020605_17_dialog_content = "¿Como alimentarlo con ingredientes extraños, tal vez?",
  str_homestory_N21yongchi_90020605_18_dialog_content = "Mmm. No me parece. A menos que las conchas, los huesos y un pez entero sean raros.",
  str_homestory_N21yongchi_90020605_19_dialog_content = "¿¡Hiciste qué!?",
  str_homestory_N21yongchi_90020605_20_dialog_content = "Y... Bueno, si la ingesta de ingredientes se atascó, podría haberle dado un buen golpe.",
  str_homestory_N21yongchi_90020605_21_dialog_content = "¡Pero un golpe muy preciso, lo prometo!",
  str_homestory_N21yongchi_90020605_22_dialog_content = "Perfectamente adaptado al problema. ¡Y no hizo ningún daño!",
  str_homestory_N21yongchi_90020605_23_dialog_content = "Lo sabía. Deberías tratar de ser un poco más amable con él.",
  str_homestory_N21yongchi_90020605_24_dialog_content = "Esperemos que se haya quedado sin energía. De lo contrario, no sé cómo lo arreglaremos.",
  str_homestory_N21yongchi_90020605_25_dialog_content = "Yo sé. Tendré más cuidado.",
  str_homestory_N21yongchi_90020605_26_dialog_content = "PlayerName, esto es genial!",
  str_homestory_N21yongchi_90020605_27_dialog_content = "Todavía no entiendo CÓMO funciona. ¡Pero estoy feliz de que lo haga!",
  str_homestory_N21yongchi_90020605_28_dialog_content = "Excelente. Volvimos a poner en funcionamiento la máquina de helados.",
  str_homestory_N21yongchi_90020605_29_dialog_content = "Oh, casi olvido por qué vine.",
  str_homestory_N21yongchi_90020605_30_dialog_content = "Es así: Fia quiere aprender a nadar, y sé que eres un buen nadador.",
  str_homestory_N21yongchi_90020605_31_dialog_content = "Así que tal vez podrías enseñarle, cuando tengas tiempo.",
  str_homestory_N21yongchi_90020605_32_dialog_content = "¿Qué, eso es todo?",
  str_homestory_N21yongchi_90020605_33_dialog_content = "Déjame agarrar esto y arreglar la máquina de helados, y luego iré a ver a Fia.",
  str_homestory_N21yongchi_90020605_34_dialog_content = "Dile que me espere junto a la piscina. Le mostraré algunos de los mejores métodos de entrenamiento de Illumina.",
  str_homestory_N21yongchi_90020605_35_dialog_content = "Fia lo conseguirá esta vez. ¡Eso será algo para celebrar!",
  str_homestory_N21yongchi_90020605_36_dialog_content = "Estará arriba.",
  str_homestory_N21yongchi_90020605_37_dialog_content = "Un poco más, ¡vamos!",
  str_homestory_N21yongchi_90020606_1_dialog_content = "Puff... Estoy exhausto.",
  str_homestory_N21yongchi_90020606_2_dialog_content = "PlayerName, pareces muy ocupado.",
  str_homestory_N21yongchi_90020606_3_dialog_content = "Debe ser agotador administrar un lugar tan grande.",
  str_homestory_N21yongchi_90020606_4_dialog_content = "Seguro es. Necesito cuidar muchas cosas diferentes aquí.",
  str_homestory_N21yongchi_90020606_5_dialog_content = "Pero estoy feliz de haber creado un lugar donde todos pueden divertirse.",
  str_homestory_N21yongchi_90020606_6_dialog_content = "Eso es cierto, pero no tienes tiempo para relajarte y divertirte, ¿verdad?",
  str_homestory_N21yongchi_90020606_7_dialog_content = "je. No, eso es cierto.",
  str_homestory_N21yongchi_90020606_8_dialog_content = "He estado trabajando desde el amanecer hasta el anochecer últimamente.",
  str_homestory_N21yongchi_90020606_9_dialog_content = "Sí. Tal como Vice y yo pensábamos.",
  str_homestory_N21yongchi_90020606_10_dialog_content = "Por eso vinimos a ayudar.",
  str_homestory_N21yongchi_90020606_11_dialog_content = "Vamos a asumir la gestión del parque acuático durante un tiempo.",
  str_homestory_N21yongchi_90020606_12_dialog_content = "Entonces podrás disfrutarlo tú también.",
  str_homestory_N21yongchi_90020606_13_dialog_content = "¿En serio?",
  str_homestory_N21yongchi_90020606_14_dialog_content = "Por supuesto. Te lo mereces.",
  str_homestory_N21yongchi_90020606_15_dialog_content = "Quiero decir, no siempre podemos beneficiarnos de todo su arduo trabajo, ¿verdad?",
  str_homestory_N21yongchi_90020606_16_dialog_content = "Asombroso. ¡He estado esperando hacer esto!",
  str_homestory_N21yongchi_90020606_17_dialog_content = "Ahora me voy a divertir desde el amanecer hasta el anochecer.",
